head.script:
scwin.screenId = "jldfil52000";

///////// 1. 변수 및 선언 영역 /////////

scwin.form = null;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 초기화 함수(init_*)를 데이터 의존성 순서로 순차 실행한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam(); // 1) 파라미터 수신 (페이징 컨텍스트 확보)
        scwin.init_rowCopy(); // 2) 전체 건수/페이지 표기 렌더
        scwin.init_pageBody(); // 3) prtDepoListForm 폼 참조 확보
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil52000.onpageload' });
    }
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name init_rowCopy
 * @description __rb0 텍스트박스에 "전체 n건 [현재/전체Page]" 표기를 dma_pageContext 값으로 렌더한다(공용 $c.data.copyRows).
 * @returns {void}
 * @hidden N
 * @example scwin.init_rowCopy();
 */
scwin.init_rowCopy = function () {
    const rowCopies = [{
        childId: "__rb0",
        fn: function () {
            const totalCount = String($c.data.readValue("dma_pageContext", "totalCountIntValue", { silent: true }));
            const currentPage = String($c.data.readValue("dma_pageContext", "currentPage", { silent: true }));
            const totalPageCount = String($c.data.readValue("dma_pageContext", "totalPageCount", { silent: true }));
            return "전체 " + totalCount + "건 [" + currentPage + "/" + totalPageCount + "Page]";
        }
    }];
    $c.data.copyRows(rowCopies);
};

/**
 * @method
 * @name init_pageBody
 * @description 페이지 본문 초기화 — 상세조회/삭제/제출에서 action 을 지정할 prtDepoListForm 폼 참조를 scwin.form 에 확보한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_pageBody();
 */
scwin.init_pageBody = function () {
    try {
        scwin.form = (document.prtDepoListForm || { elements: [] });
    } catch (ex) {
        $c.exception.handleError(ex, { context: 'jldfil52000.onpageload' });
    }
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터를 dma_pageContext 로 수신한다(공용 $c.data.recvParamData, 이름 고정 "paramData").
 * @returns {void}
 * @hidden N
 * @example scwin.init_recvParam();
 */
scwin.init_recvParam = function () {
    $c.data.recvParamData('dma_pageContext');
};

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.searchType = undefined;
scwin.form = undefined;


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name grd_prtDepoList_oncellclick
 * @description 목록 셀 클릭 — 비고(__rowAct) 컬럼이면 상태 코드에 따라 제출(sendPrtDepoWithd)/수정요청 팝업(openAdjReqPop)을 실행하고, 그 외 컬럼이면 상세조회(viewDetail)로 이동한다.
 * @param {Number} rowIndex 클릭한 행 인덱스
 * @param {Number} columnIndex 클릭한 열 인덱스
 * @param {String} columnId 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example (grd_prtDepoList ev:oncellclick 바인딩으로 자동 호출)
 */
scwin.grd_prtDepoList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_prtDepoList');
        const r = dl && dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) {
            return;
        }
        const approvYn = r["lstApprovYn"];
        const statCd = r["listProcsStatCd"];
        const prtdepoNo = r["prtdepoNo"];
        if (columnId === "__rowAct") {
            if (approvYn === '0' && statCd === '') {
                await scwin.sendPrtDepoWithd(prtdepoNo, "2");
                return;
            }
            if ((approvYn === '0' || approvYn === '3') && statCd === '35') {
                await scwin.sendPrtDepoWithd(prtdepoNo, "3");
                return;
            }
            if ((approvYn === '0' || approvYn === '7') && statCd === '37') {
                await scwin.sendPrtDepoWithd(prtdepoNo, "3");
                return;
            }
            if (approvYn === '7' && statCd === '38') {
                await scwin.sendPrtDepoWithd(prtdepoNo, "3");
                return;
            }
            if (approvYn === '3' && (statCd === '33' || statCd === '36' || statCd === '37')) {
                scwin.openAdjReqPop(prtdepoNo, "150");
                return;
            }
            return;
        }
        if (approvYn === '0' && (statCd === '' || statCd === '35')) {
            await scwin.viewDetail(prtdepoNo, approvYn, statCd);
            return;
        }
        if (approvYn === '3' && statCd === '35') {
            await scwin.viewDetail(prtdepoNo, approvYn, statCd);
            return;
        }
        if ((approvYn === '0' || approvYn === '7') && statCd === '37') {
            await scwin.viewDetail(prtdepoNo, approvYn, statCd);
            return;
        }
        if (approvYn === '7' && statCd === '38') {
            await scwin.viewDetail(prtdepoNo, approvYn, statCd);
            return;
        }
        await scwin.viewDetail(prtdepoNo, approvYn, statCd);
        return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_prtDepoList.oncellclick' });
    }
};

/**
 * @event
 * @name btn_newWrite_onclick
 * @description [신규작성] 버튼 클릭 — 의무보유주식 처분 신규작성 화면(jldfil52100)으로 이동한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (btn_newWrite ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_newWrite_onclick = function (e) {
    try {
        const ev = e;
        const event = ev;
        const srcEl = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.newWrite();
    } catch (ex) {
        $c.exception.handleError(ex, { context: 'jldfil52000.btn_newWrite_onclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name tx_viewDetail
 * @description 의무보유주식 처분 상세 내역을 서버에 조회해 dlt_prtDepoList 에 적재한다. 실패 응답 메시지는 알림으로 표출한다.
 * @returns {Object} executeDynamic 응답 객체(resObj), 통신 오류 시 null
 * @hidden N
 * @example const res = await scwin.tx_viewDetail();
 */
scwin.tx_viewDetail = async function () {
    const sbmOptions = {
        id: "tx_viewDetail",
        method: "post",
        action: "/listInvstg/prtDepo.do?method=loadDetail&bzCd=6",
        ref: "dma_viewDetailReq",
        target: "dlt_prtDepoList=body",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: "jldfil52000.tx_viewDetail" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) { await $c.win.alert(res.responseJSON.message); }
        return res;
    }
    return res;
};

/**
 * @method
 * @name tx_searchCorpListByBeginIndex
 * @description 의무보유주식 처분 목록을 서버에 조회(getPrtDepoList)해 dlt_prtDepoList 에 적재한다. 실패 응답 메시지는 알림으로 표출한다.
 * @returns {Object} executeDynamic 응답 객체(resObj), 통신 오류 시 null
 * @hidden N
 * @example const res = await scwin.tx_searchCorpListByBeginIndex();
 */
scwin.tx_searchCorpListByBeginIndex = async function () {
    const sbmOptions = {
        id: "tx_searchCorpListByBeginIndex",
        method: "post",
        action: "/listInvstg/prtDepoList.do?method=getPrtDepoList",
        ref: "dma_searchCorpListByBeginIndexReq",
        target: "dlt_prtDepoList=body",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: "jldfil52000.tx_searchCorpListByBeginIndex" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) { await $c.win.alert(res.responseJSON.message); }
        return res;
    }
    return res;
};

/**
 * @method
 * @name tx_fn_delete
 * @description 의무보유주식 처분 건 삭제(delPrtDepoWithd)를 서버에 요청하고 갱신 목록을 dlt_prtDepoList 에 적재한다. 실패 응답 메시지는 알림으로 표출한다.
 * @returns {Object} executeDynamic 응답 객체(resObj), 통신 오류 시 null
 * @hidden N
 * @example const res = await scwin.tx_fn_delete();
 */
scwin.tx_fn_delete = async function () {
    const sbmOptions = {
        id: "tx_fn_delete",
        method: "post",
        action: "/listInvstg/prtDepoList.do",
        ref: "dma_deleteReq",
        target: "dlt_prtDepoList=body",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: "jldfil52000.tx_fn_delete" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) { await $c.win.alert(res.responseJSON.message); }
        return res;
    }
    return res;
};

/**
 * @method
 * @name tx_sendPrtDepoWithd
 * @description 의무보유주식 처분 건 제출(sendPrtDepoWithd)을 서버에 요청하고 갱신 목록을 dlt_prtDepoList 에 적재한다. 실패 응답 메시지는 알림으로 표출한다.
 * @returns {Object} executeDynamic 응답 객체(resObj), 통신 오류 시 null
 * @hidden N
 * @example const res = await scwin.tx_sendPrtDepoWithd();
 */
scwin.tx_sendPrtDepoWithd = async function () {
    const sbmOptions = {
        id: "tx_sendPrtDepoWithd",
        method: "post",
        action: "/listInvstg/prtDepoList.do",
        ref: "dma_sendPrtDepoWithdReq",
        target: "dlt_prtDepoList=body",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: "jldfil52000.tx_sendPrtDepoWithd" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) { await $c.win.alert(res.responseJSON.message); }
        return res;
    }
    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @event
 * @name grd_prtDepoList_fillAct
 * @description 목록 적재 후 각 행의 승인여부/처리상태 코드를 판정해 비고(__rowAct) 컬럼에 "제출"/"수정요청"/"-" 표기를 채운다.
 * @returns {void}
 * @hidden N
 * @example (dlt_prtDepoList ev:ondataload 바인딩으로 자동 호출)
 */
scwin.grd_prtDepoList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_prtDepoList');
        if (!dl || !dl.getTotalRow) {
            return;
        }
        const totalRow = dl.getTotalRow();
        for (let i = 0; i < totalRow; i++) {
            const r = dl.getRowJSON(i);
            let v = '-';
            if (r) {
                const approvYn = r["lstApprovYn"];
                const statCd = r["listProcsStatCd"];
                if (approvYn === '0' && statCd === '') {
                    v = "제출";
                } else if ((approvYn === '0' || approvYn === '3') && statCd === '35') {
                    v = "제출";
                } else if ((approvYn === '0' || approvYn === '7') && statCd === '37') {
                    v = "제출";
                } else if (approvYn === '7' && statCd === '38') {
                    v = "제출";
                } else if (approvYn === '3' && (statCd === '33' || statCd === '36' || statCd === '37')) {
                    v = "수정요청";
                }
            }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_prtDepoList.fillAct' });
    }
};

/**
 * @method
 * @name viewDetail
 * @description 승인여부/처리상태 코드 조합으로 searchType(1~5)을 판정한 뒤 상세조회 요청 전문을 채우고 tx_viewDetail 로 상세 내역을 조회한다.
 * @param {String} prtDepoNo 의무보유주식 처분 번호
 * @param {String} approvYn 승인 여부 코드(lstApprovYn)
 * @param {String} procsStatCd 처리 상태 코드(listProcsStatCd)
 * @returns {void}
 * @hidden N
 * @example await scwin.viewDetail(prtdepoNo, lstApprovYn, listProcsStatCd);
 */
scwin.viewDetail = async function (prtDepoNo, approvYn, procsStatCd) {
    const reqMap = $c.util.getComponent('dma_viewDetailReq');
    reqMap.set('prtDepoNo', prtDepoNo);
    if (approvYn === '0' || approvYn === '7') {
        if (procsStatCd === '38') {
            scwin.searchType = '5';
        } else {
            scwin.searchType = '2';
        }
    } else {
        if (approvYn === '2') {
            if (procsStatCd === '38') {
                scwin.searchType = '5';
            } else {
                scwin.searchType = '1';
            }
        } else {
            if (approvYn === '3') {
                if (procsStatCd === '34') {
                    scwin.searchType = '1';
                } else {
                    if (procsStatCd === '35') {
                        scwin.searchType = '3';
                    } else {
                        scwin.searchType = '1';
                    }
                }
            } else {
                if (approvYn === '8') {
                    scwin.searchType = '4';
                } else {
                    if (approvYn === '9') {
                        scwin.searchType = '5';
                    }
                }
            }
        }
    }
    reqMap.set('searchType', scwin.searchType);
    scwin.form.action = '/listInvstg/prtDepo.do?method=loadDetail&bzCd=6';
    reqMap.set('method', 'loadDetail');
    await scwin.tx_viewDetail();
};


/**
 * @method
 * @name newWrite
 * @description 의무보유주식 처분 신규작성 화면(jldfil52100)으로 페이지 프레임을 전환한다.
 * @returns {void}
 * @hidden N
 * @example scwin.newWrite();
 */
scwin.newWrite = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil52100/jldfil52100.xml');
};


/**
 * @method
 * @name fn_New_Display
 * @description select_new_write 컴포넌트를 표시(show)한다. 대상 컴포넌트가 없으면 경고 로그만 남긴다.
 * @returns {void}
 * @hidden N
 * @example scwin.fn_New_Display();
 */
scwin.fn_New_Display = function () {
    const comp = $c.util.getComponent('select_new_write');
    (comp && comp.show ? comp.show() : console.warn('[sdd] show 대상 미해결: ' + 'select_new_write'));
};


/**
 * @method
 * @name fncSearch
 * @description 요청 전문(dma_viewDetailReq)의 pageIndex 를 확정한 뒤 목록 재조회(searchCorpListByBeginIndex)를 수행한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.fncSearch();
 */
scwin.fncSearch = async function () {
    const reqMap = $c.util.getComponent('dma_viewDetailReq');
    const pageIndex = reqMap.get('pageIndex');
    reqMap.set('pageIndex', pageIndex);
    await scwin.searchCorpListByBeginIndex();
};


/**
 * @method
 * @name searchCorpListByBeginIndex
 * @description prtDepoListForm 의 action 을 목록 조회 URL 로 지정하고 tx_searchCorpListByBeginIndex 로 목록을 조회한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.searchCorpListByBeginIndex();
 */
scwin.searchCorpListByBeginIndex = async function () {
    (document.prtDepoListForm || { elements: [] }).action = "/listInvstg/prtDepoList.do?method=getPrtDepoList";
    await scwin.tx_searchCorpListByBeginIndex();
};


/**
 * @method
 * @name fn_delete
 * @description 삭제 확인(confirm) 후 요청 전문을 채우고 tx_fn_delete 로 해당 처분 건 삭제를 요청한다.
 * @param {String} prtDepoNo 의무보유주식 처분 번호
 * @returns {void}
 * @hidden N
 * @example await scwin.fn_delete(prtdepoNo);
 */
scwin.fn_delete = async function (prtDepoNo) {
    const reqMap = $c.util.getComponent('dma_viewDetailReq');
    reqMap.set('prtDepoNo', prtDepoNo);
    const rse = await $c.win.confirm("삭제 하시겠습니까? ");
    if (rse) {
        scwin.form.action = '/listInvstg/prtDepoList.do';
        reqMap.set('method', 'delPrtDepoWithd');
        await scwin.tx_fn_delete();
    }
};


/**
 * @method
 * @name sendPrtDepoWithd
 * @description 제출 확인(confirm) 후 요청 전문(처분번호·갱신유형)을 채우고 tx_sendPrtDepoWithd 로 해당 처분 건 제출을 요청한다.
 * @param {String} prtDepoNo 의무보유주식 처분 번호
 * @param {String} updateType 갱신 유형 코드(searchType 으로 전송)
 * @returns {void}
 * @hidden N
 * @example await scwin.sendPrtDepoWithd(prtdepoNo, "2");
 */
scwin.sendPrtDepoWithd = async function (prtDepoNo, updateType) {
    scwin.form = (document.prtDepoListForm || { elements: [] });
    const rse = await $c.win.confirm("제출 하시겠습니까? ");
    if (rse) {
        const reqMap = $c.util.getComponent('dma_viewDetailReq');
        reqMap.set('prtDepoNo', prtDepoNo);
        reqMap.set('searchType', updateType);
        scwin.form.action = '/listInvstg/prtDepoList.do';
        reqMap.set('method', 'sendPrtDepoWithd');
        await scwin.tx_sendPrtDepoWithd();
    }
};



/**
 * @method
 * @name openAdjReqPop
 * @description 수정요청 팝업(jldfil59411)을 열어 해당 처분 건의 수정요청 내역을 확인한다.
 * @param {String} prtdepoNo 의무보유주식 처분 번호(bzProcsNo 로 전달)
 * @param {String} listInvstgBzTpCd 상장심사 업무 유형 코드
 * @returns {void}
 * @hidden N
 * @example await scwin.openAdjReqPop(prtdepoNo, "150");
 */
scwin.openAdjReqPop = async function (prtdepoNo, listInvstgBzTpCd) {
    const data = { bzProcsNo: prtdepoNo, listInvstgBzTpCd: listInvstgBzTpCd, listBzDtlTpCd: "23", callbackFn: "scwin.popupCallback" };
    const options = { id: "jldfil59411", popupName: "상장공시제출시스템 수정요청", width: 900, height: 380, frameModal: "top" };
    await $c.win.openPopup("/jldfil59411/jldfil59411.xml", options, data);
};

/**
 * @event
 * @name krxpage_pagenavigator_78_onclick
 * @description 페이지 내비게이터 클릭 — 선택한 페이지 번호를 요청 전문(pageIndex)에 반영하고 목록을 재조회(fncSearch)한다.
 * @param {Number} index 클릭한 페이지 번호
 * @returns {void}
 * @hidden N
 * @example (krxpage_pagenavigator_78 ev:onclick 바인딩으로 자동 호출)
 */
scwin.krxpage_pagenavigator_78_onclick = function (index) {
    try {
        $c.util.getComponent('dma_viewDetailReq').set('pageIndex', index);
    } catch (e) {
        $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_78.page' });
    }
    scwin.fncSearch();
};
